# Script lifecycle: subscriptions are owned by each script, no callback registry.
start = '    pub fn start_script(\n'
end = '    /// 停止脚本引擎'
new_start_script = '''    pub fn start_script(\n        &mut self,\n        session_id: &str,\n        code: &str,\n        app_handle: tauri::AppHandle,\n    ) -> Result<(), String> {\n        if let Some(handle) = self.sessions.get_mut(session_id) {\n            let io = handle.io.clone().ok_or("通信能力不可用")?;\n            if let Some(tx) = &handle.script_tx {\n                return tx.send(ScriptCmd::LoadScript(code.to_string()))\n                    .map_err(|e| format!("发送脚本失败: {}", e));\n            }\n            let subscription = io.primary().map(|_| io.subscribe()).transpose()\n                .map_err(|e| e.to_string())?;\n            let (tx, rx) = mpsc::sync_channel::<ScriptCmd>(4096);\n            let shutdown = Arc::new(AtomicBool::new(false));\n            let thread = spawn_script_thread(\n                io, subscription, app_handle, rx, session_id.to_string(), shutdown.clone(),\n            );\n            tx.send(ScriptCmd::LoadScript(code.to_string()))\n                .map_err(|e| format!("发送脚本失败: {}", e))?;\n            handle.script_tx = Some(tx);\n            handle.script_thread = Some(thread);\n            handle.script_shutdown = Some(shutdown);\n            return Ok(());\n        }\n        let not_found = self.session_not_found(session_id);\n        let (parent_id, sub_idx) = self.find_sub_connection_index(session_id).ok_or(not_found)?;\n        let handle = self.sessions.get_mut(&parent_id).ok_or("父会话不存在")?;\n        let sub = &mut handle.sub_connections[sub_idx];\n        if let Some(tx) = &sub.script_tx {\n            return tx.send(ScriptCmd::LoadScript(code.to_string()))\n                .map_err(|e| format!("发送脚本失败: {}", e));\n        }\n        let io = sub.io.clone();\n        let subscription = io.subscribe().map_err(|e| e.to_string())?;\n        let (tx, rx) = mpsc::sync_channel::<ScriptCmd>(4096);\n        let shutdown = Arc::new(AtomicBool::new(false));\n        let thread = spawn_script_thread(\n            io, Some(subscription), app_handle, rx, session_id.to_string(), shutdown.clone(),\n        );\n        tx.send(ScriptCmd::LoadScript(code.to_string()))\n            .map_err(|e| format!("发送脚本失败: {}", e))?;\n        sub.script_tx = Some(tx);\n        sub.script_thread = Some(thread);\n        sub.script_shutdown = Some(shutdown);\n        Ok(())\n    }\n\n'''
s = between(s, start, end, new_start_script)

start = '    pub fn stop_script(&mut self, session_id: &str) -> Result<(), String> {'
end = '    /// 获取活跃会话 ID'
new_stop = '''    pub fn stop_script(&mut self, session_id: &str) -> Result<(), String> {\n        if let Some(handle) = self.sessions.get_mut(session_id) {\n            Self::stop_script_fields(\n                &mut handle.script_shutdown, &mut handle.script_tx, &mut handle.script_thread,\n            );\n            return Ok(());\n        }\n        let not_found = self.session_not_found(session_id);\n        let (parent_id, sub_idx) = self.find_sub_connection_index(session_id).ok_or(not_found)?;\n        let handle = self.sessions.get_mut(&parent_id).ok_or("父会话不存在")?;\n        let sub = &mut handle.sub_connections[sub_idx];\n        Self::stop_script_fields(&mut sub.script_shutdown, &mut sub.script_tx, &mut sub.script_thread);\n        Ok(())\n    }\n\n    fn stop_script_fields(\n        shutdown: &mut Option<Arc<AtomicBool>>,\n        tx: &mut Option<mpsc::SyncSender<ScriptCmd>>,\n        thread: &mut Option<std::thread::JoinHandle<()>>,\n    ) {\n        if let Some(flag) = shutdown.take() { flag.store(true, Ordering::SeqCst); }\n        if let Some(tx) = tx.take() { let _ = tx.send(ScriptCmd::Shutdown); }\n        if let Some(thread) = thread.take() { let _ = thread.join(); }\n    }\n\n'''
s = between(s, start, end, new_stop)

# Reconnect uses a fresh DataPlane runtime.
start = '    pub fn reconnect_session(\n'
end = '    /// 为 Inline 传输预留当前 Session 的唯一活动槽。'
new_reconnect = '''    pub fn reconnect_session(\n        &mut self,\n        session_id: &str,\n        runtime: DataPlaneRuntime,\n        on_data: Box<dyn Fn(String, Vec<u8>) + Send + 'static>,\n        on_disconnect: Box<dyn Fn(String, DisconnectInfo) + Send + 'static>,\n        app_handle: tauri::AppHandle,\n    ) -> Result<serde_json::Value, String> {\n        let not_found = self.session_not_found(session_id);\n        let handle = self.sessions.get_mut(session_id).ok_or(not_found)?;\n        if let Some(flag) = &handle.stats_cancel_flag { flag.store(true, Ordering::SeqCst); }\n        if let Some(old) = &handle.data_plane { old.request_shutdown(); }\n        let connected_at = Some(\n            std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)\n                .unwrap_or_default().as_millis() as u64,\n        );\n        let encoding = handle.params.get("encoding").and_then(|v| v.as_str()).unwrap_or("utf-8");\n        let io = Arc::new(SessionIo::new(Some(runtime.handle.clone()), None, encoding));\n        let data_plane = SessionDataPlane::attach(runtime, session_id.to_string(), on_data, on_disconnect)\n            .map_err(|e| e.to_string())?;\n        let stats_flag = Arc::new(AtomicBool::new(false));\n        Self::start_stats_collector(\n            app_handle.clone(), session_id.to_string(), io.clone(), connected_at, stats_flag.clone(),\n        );\n        if handle.script_shutdown.is_some() {\n            let _ = app_handle.emit("script-log", serde_json::json!({\n                "session_id": session_id,\n                "message": "[Engine] 会话已重连 — 请重新启动脚本引擎",\n            }));\n            Self::stop_script_fields(\n                &mut handle.script_shutdown, &mut handle.script_tx, &mut handle.script_thread,\n            );\n        }\n        handle.data_plane = Some(data_plane);\n        handle.io = Some(io);\n        handle.state = SessionState::Connected;\n        handle.connected_at = connected_at;\n        handle.stats_cancel_flag = Some(stats_flag);\n        Ok(handle.params.clone())\n    }\n\n'''
s = between(s, start, end, new_reconnect)

# Disconnect callbacks now only mark/cancel; DataPlane owns transport lifecycle.
start = '    pub fn mark_disconnected(&mut self, session_id: &str) {'
end = '    /// 标记子连接为已断开'
new_mark = '''    pub fn mark_disconnected(&mut self, session_id: &str) {\n        if let Some(handle) = self.sessions.get_mut(session_id) {\n            handle.state = SessionState::Disconnected;\n            for sub in &mut handle.sub_connections {\n                sub.state = SessionState::Disconnected;\n                if let Some(flag) = &sub.stats_cancel_flag { flag.store(true, Ordering::SeqCst); }\n                if let Some(data_plane) = &sub.data_plane { data_plane.request_shutdown(); }\n            }\n            handle.transfer_scheduler.cancel_for_shutdown();\n            if let Some(flag) = &handle.script_shutdown { flag.store(true, Ordering::SeqCst); }\n            if let Some(tx) = handle.script_tx.take() { let _ = tx.send(ScriptCmd::Shutdown); }\n            if let Some(flag) = &handle.stats_cancel_flag { flag.store(true, Ordering::SeqCst); }\n            if let Some(bridge) = handle.virtual_external_pathridge.take() { bridge.shutdown(); }\n        }\n    }\n\n'''
s = between(s, start, end, new_mark)

start = '    pub fn mark_sub_disconnected(\n'
end = '    /// 启动 I/O 统计采集器'
new_mark_sub = '''    pub fn mark_sub_disconnected(\n        &mut self,\n        parent_id: &str,\n        channel_id: &str,\n        retain_terminal: bool,\n    ) {\n        if let Some(handle) = self.sessions.get_mut(parent_id) {\n            if let Some(sub) = handle.sub_connections.iter_mut().find(|sub| sub.id == channel_id) {\n                sub.state = SessionState::Disconnected;\n                sub.retain_terminal = retain_terminal;\n                if let Some(flag) = &sub.stats_cancel_flag { flag.store(true, Ordering::SeqCst); }\n            }\n        }\n    }\n\n'''
s = between(s, start, end, new_mark_sub)

# Stats source is the canonical SessionIo/DataPlane counter, not duplicate atomics.
start = '    fn start_stats_collector(\n'
end = '    /// 获取会话持久化文件路径'
new_stats = '''    fn start_stats_collector(\n        app_handle: tauri::AppHandle,\n        tab_id: String,\n        io: Arc<SessionIo>,\n        connected_at: Option<u64>,\n        cancel_flag: Arc<AtomicBool>,\n    ) {\n        Self::spawn_stats_collector(app_handle, tab_id, io, connected_at, cancel_flag);\n    }\n\n    pub fn spawn_stats_collector(\n        app_handle: tauri::AppHandle,\n        tab_id: String,\n        io: Arc<SessionIo>,\n        connected_at: Option<u64>,\n        cancel_flag: Arc<AtomicBool>,\n    ) {\n        std::thread::spawn(move || {\n            let mut last_tx = 0;\n            let mut last_rx = 0;\n            loop {\n                std::thread::sleep(Duration::from_secs(1));\n                if cancel_flag.load(Ordering::SeqCst) { break; }\n                let tx = io.tx_bytes();\n                let rx = io.rx_bytes();\n                if tx != last_tx || rx != last_rx {\n                    last_tx = tx; last_rx = rx;\n                    let _ = app_handle.emit("session-stats", SessionStats {\n                        tab_id: tab_id.clone(), tx_bytes: tx, rx_bytes: rx, connected_at,\n                    });\n                }\n            }\n        });\n    }\n\n'''
s = between(s, start, end, new_stats)

P.write_text(s)
print('SessionStore migrated to SessionDataPlane')
